css:
.smfsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2b2419;
    background: linear-gradient(155deg, #f7f2e8 0%, #efe6d4 50%, #e8dcc4 100%);
    border-radius: 18px;
}

.smfsim-container * {
    box-sizing: border-box;
}

.smfsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #2f3e34 0%, #3c5145 55%, #54402a 100%);
    color: #f5efe2;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #54402a;
    box-shadow: 0 12px 30px rgba(47, 62, 52, 0.35);
}

.smfsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #fbf6ea;
}

.smfsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #e8b35a;
    background: rgba(232, 179, 90, 0.14);
    border: 1px solid rgba(232, 179, 90, 0.35);
    padding: 5px 14px;
    border-radius: 999px;
}

.smfsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dcd2bf;
}

.smfsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #5d5340;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.smfsim-period-counter #currentDay,
.smfsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #b5701f;
}

.smfsim-round-name {
    background: rgba(60, 81, 69, 0.12);
    color: #3c5145;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.smfsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a4421f;
    background: rgba(164, 66, 31, 0.10);
    border: 1px solid rgba(164, 66, 31, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.smfsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.smfsim-status-card {
    background: #fffdf7;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #ddd0b6;
    box-shadow: 0 6px 16px rgba(84, 64, 42, 0.12);
    border-top: 4px solid #8a7350;
}

.smfsim-card-otif { border-top-color: #2f7d5b; }
.smfsim-card-cash { border-top-color: #b5701f; }
.smfsim-card-board { border-top-color: #3c6ea5; }
.smfsim-card-exposure { border-top-color: #a4421f; }

.smfsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #877a5e;
}

.smfsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2b2419;
    font-variant-numeric: tabular-nums;
}

.smfsim-card-otif .smfsim-value { color: #2f7d5b; }
.smfsim-card-cash .smfsim-value { color: #b5701f; }
.smfsim-card-board .smfsim-value { color: #3c6ea5; }
.smfsim-card-exposure .smfsim-value { color: #a4421f; }

.smfsim-sublabel {
    font-size: 0.76rem;
    color: #8c8068;
    line-height: 1.35;
}

.smfsim-otif-good .smfsim-value { color: #1f7a4d; }
.smfsim-otif-bad .smfsim-value { color: #a4421f; }
.smfsim-otif-good { border-top-color: #1f7a4d; }
.smfsim-otif-bad { border-top-color: #a4421f; }

.smfsim-exposure-high { border-top-color: #c4391a; }
.smfsim-exposure-high .smfsim-value { color: #c4391a; }
.smfsim-exposure-low { border-top-color: #2f7d5b; }
.smfsim-exposure-low .smfsim-value { color: #2f7d5b; }

.smfsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #2f3e34;
    border: 1px solid #54402a;
    color: #eee5d2;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.smfsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e8b35a;
}

.smfsim-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf7;
    border-left: 5px solid #b5701f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(84, 64, 42, 0.10);
}

.smfsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.smfsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #2b2419;
    margin-bottom: 6px;
}

.smfsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a4232;
}

.smfsim-briefing-text strong { color: #b5701f; }
.smfsim-briefing-text em { color: #a4421f; font-style: italic; }

.smfsim-controls {
    background: #fffdf7;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #ddd0b6;
    box-shadow: 0 6px 16px rgba(84, 64, 42, 0.10);
}

.smfsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #2b2419;
    border-bottom: 2px solid #e4d9c0;
    padding-bottom: 8px;
}

.smfsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3a3325;
    margin: 14px 0 6px;
}

.smfsim-container select,
.smfsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c9b994;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf7ec;
    color: #2b2419;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.smfsim-container select:focus,
.smfsim-container input[type="number"]:focus {
    outline: none;
    border-color: #b5701f;
    box-shadow: 0 0 0 3px rgba(181, 112, 31, 0.18);
}

.smfsim-container select option {
    background-color: #fbf7ec;
    color: #2b2419;
}

.smfsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b5701f;
}

.smfsim-range-readout,
.smfsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6b6049;
    margin-top: 4px;
}

.smfsim-range-readout span:last-child,
.smfsim-alloc-readout span:nth-child(2) {
    color: #b5701f;
    font-weight: 800;
}

.smfsim-hint {
    font-size: 0.8rem;
    color: #8c8068;
    margin-top: 4px;
    line-height: 1.4;
}

.smfsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.smfsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6efdf;
    border: 1px solid #ddd0b6;
    border-radius: 9px;
    padding: 8px 12px;
}

.smfsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #4a4232;
}

.smfsim-alloc-row input[type="number"] {
    width: 88px;
    flex: 0 0 88px;
}

.smfsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.smfsim-container .btn-primary {
    background: linear-gradient(135deg, #8a4f12 0%, #b5701f 55%, #e8b35a 100%);
    border: none;
    color: #2b1c08;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(138, 79, 18, 0.32);
}

.smfsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.smfsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c9b994;
    color: #6b6049;
    background: transparent;
}

.smfsim-coach {
    background: linear-gradient(160deg, #2f3e34 0%, #3a3325 100%);
    color: #ece2cf;
    border: 1px solid #54402a;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(47, 62, 52, 0.25);
}

.smfsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e8b35a;
    margin-bottom: 8px;
}

.smfsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.smfsim-coach-body strong { color: #e8b35a; }
.smfsim-coach-body em { color: #f0a878; font-style: italic; }

.smfsim-history,
.smfsim-chart {
    background: #fffdf7;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #ddd0b6;
    box-shadow: 0 6px 16px rgba(84, 64, 42, 0.10);
}

.smfsim-history h3,
.smfsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #2b2419;
}

.smfsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a4232;
}

.smfsim-container table#usfHistoryTable th {
    background: #2f3e34;
    color: #e8b35a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #54402a;
}

.smfsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e4d9c0;
    color: #4a4232;
}

.smfsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8f2e4;
}

.smfsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .smfsim-container {
        padding: 14px;
    }
    .smfsim-header h1 {
        font-size: 1.7rem;
    }
    .smfsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .smfsim-value {
        font-size: 2rem;
    }
    .smfsim-clock {
        margin-left: 0;
    }
    .smfsim-period-counter {
        font-size: 0.88rem;
    }
    .smfsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .smfsim-alloc-row {
        flex-wrap: wrap;
    }
    .smfsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .smfsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* === smfsim-cm: completion debrief (appended, adapter 1.1.0) === */
.smfsim-cm { max-width: 640px; margin: 0 auto; font-family: inherit; }
.smfsim-cm-head { display: flex; align-items: baseline; gap: 14px; flex-wrap: wrap; margin-bottom: 14px; }
.smfsim-cm-score { font-size: 3rem; font-weight: 800; line-height: 1; color: #0b3d5c; }
.smfsim-cm-max { font-size: 1.1rem; font-weight: 600; color: #6b7a86; margin-left: 2px; }
.smfsim-cm-grade { font-size: 1.25rem; font-weight: 700; color: #123; }
.smfsim-cm-badges { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
.smfsim-cm-badge { font-size: .82rem; font-weight: 600; padding: 4px 10px; border-radius: 999px; border: 1px solid transparent; }
.smfsim-cm-ok { background: #e4f5ea; color: #1c7a43; border-color: #b7e2c7; }
.smfsim-cm-no { background: #fdecec; color: #b23b3b; border-color: #f3c4c4; }
.smfsim-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(96px, 1fr)); gap: 10px; margin-bottom: 16px; }
.smfsim-cm-kpi { background: #f4f7f9; border: 1px solid #e1e8ed; border-radius: 8px; padding: 10px 8px; text-align: center; }
.smfsim-cm-kpi-v { font-size: 1.2rem; font-weight: 700; color: #0b3d5c; }
.smfsim-cm-kpi-l { font-size: .74rem; color: #6b7a86; margin-top: 3px; }
.smfsim-cm-insights { margin: 0; padding-left: 20px; }
.smfsim-cm-insights li { margin: 5px 0; line-height: 1.4; }

