(function() {
    'use strict';

    class SMFAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Five Steps to Value`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Smoky Mountain Foods, Inc. — all USD).
            this.OTIF_START = 89;        // % OTIF to the at-risk customer
            this.OTIF_TARGET = 96;       // % required by the service-watch letter
            this.BUDGET = 40;            // US$40M three-year transformation budget
            this.EXCESS_INV = 60;        // ~US$60M+ excess inventory (cash to release)
            this.ERP_COST = 28;          // ~US$28M for the single-ERP unification
            this.CUSTOMER = 275;         // ~US$275M of revenue at the at-risk customer

            // Concept truths (the integrated, service-led, S&OP-first answer).
            this.TRUE_GAP = `strategy`;
            this.TRUE_THREAT = `service`;
            this.TRUE_PRIORITY = `service`;
            this.TRUE_PHASE = `sop`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    otif: this.OTIF_START,   // % on-time-in-full to the at-risk customer
                    cashReleased: 0,         // US$M working capital freed
                    board: 25,               // board confidence / gate buy-in (0–100)
                    exposure: 60,            // delisting exposure (0–100, lower better)
                    budgetUsed: 0,           // US$M of the $40M budget committed
                    erpFirst: false,
                    overBudgetPlan: false,
                    costMisaligned: false,
                    noGateTest: false,
                    otifHistory: [this.OTIF_START],
                    cashHistory: [0],
                    boardHistory: [25],
                    exposureHistory: [60],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / wrong-leaning mix —
                // a blind click-through must not auto-win (ERP-heavy, cost-leaning, weak tests).
                state.decisions = {
                    gap: `operations`,
                    threat: `cost`,
                    position: 50,
                    priority: `cost`,
                    count: `some`,
                    align: `partial`,
                    focus: 50,
                    sop: 6,
                    network: 8,
                    wc: 4,
                    talent: 4,
                    erp: 10,
                    auto: 8,
                    phase: `erp`,
                    test: `directional`,
                    fund: `ask`,
                    risk: `confident`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const gp = document.getElementById(`gapInput`);
                const th = document.getElementById(`threatInput`);
                const po = document.getElementById(`positionInput`);
                if (gp) decisions.gap = gp.value;
                if (th) decisions.threat = th.value;
                if (po) decisions.position = parseInt(po.value, 10);
                if (!Number.isFinite(decisions.position) || decisions.position < 0 || decisions.position > 100) {
                    warn(`warn_position_range`); return false;
                }
            } else if (round === 2) {
                const pr = document.getElementById(`priorityInput`);
                const ct = document.getElementById(`countInput`);
                const al = document.getElementById(`alignInput`);
                const fo = document.getElementById(`focusInput`);
                if (pr) decisions.priority = pr.value;
                if (ct) decisions.count = ct.value;
                if (al) decisions.align = al.value;
                if (fo) decisions.focus = parseInt(fo.value, 10);
                if (!Number.isFinite(decisions.focus) || decisions.focus < 0 || decisions.focus > 100) {
                    warn(`warn_focus_range`); return false;
                }
            } else if (round === 3) {
                const ids = [`sopInput`, `networkInput`, `wcInput`, `talentInput`, `erpInput`, `autoInput`];
                const keys = [`sop`, `network`, `wc`, `talent`, `erp`, `auto`];
                for (let i = 0; i < ids.length; i++) {
                    const el = document.getElementById(ids[i]);
                    if (el) decisions[keys[i]] = parseFloat(el.value);
                }
                const ph = document.getElementById(`phaseInput`);
                if (ph) decisions.phase = ph.value;
                const parts = keys.map((k) => decisions[k]);
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(parts.reduce((a, b) => a + b, 0));
                if (total > this.BUDGET) {
                    warn(`warn_alloc_over`); return false;
                }
                if (total < this.BUDGET) {
                    warn(`warn_alloc_under`); return false;
                }
            } else if (round === 4) {
                const te = document.getElementById(`testInput`);
                const fu = document.getElementById(`fundInput`);
                const ri = document.getElementById(`riskInput`);
                const cv = document.getElementById(`convictionInput`);
                if (te) decisions.test = te.value;
                if (fu) decisions.fund = fu.value;
                if (ri) decisions.risk = ri.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let otifDelta = 0, cashDelta = 0, boardDelta = 0, exposureDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: reframe 'fix operations' into 'build a strategy' (Pedagogy 1).
                switch (d.gap) {
                    case `strategy`: boardDelta += 12; exposureDelta -= 4; coachKey = `coach_r1_strategy`; break;
                    case `operations`: boardDelta += 2; exposureDelta += 4; coachKey = `coach_r1_operations`; break;
                    case `it`: boardDelta -= 2; exposureDelta += 6; coachKey = `coach_r1_it`; break;
                    case `people`: boardDelta += 1; exposureDelta += 3; coachKey = `coach_r1_people`; break;
                }

                // Name the biggest threat to value (service to the at-risk customer).
                switch (d.threat) {
                    case `service`: boardDelta += 8; exposureDelta -= 10; if (d.gap === `strategy`) coachKey = `coach_r1_sharp`; break;
                    case `cash`: boardDelta += 4; exposureDelta += 2; break;
                    case `systems`: boardDelta += 2; exposureDelta += 3; break;
                    case `cost`: boardDelta -= 2; exposureDelta += 6; ds.costMisaligned = true; coachKey = `coach_r1_cost`; break;
                }

                if (d.position >= 60) { boardDelta += 6; exposureDelta -= 4; }
                else if (d.position <= 25) { boardDelta -= 5; exposureDelta += 5; coachKey = `coach_r1_lowposition`; }

                summaryKey = (d.gap === `strategy` && d.threat === `service`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Plan: a coherent few priorities aligned to competitive position (Pedagogy 2).
                switch (d.priority) {
                    case `service`: boardDelta += 10; otifDelta += 1; exposureDelta -= 6; coachKey = `coach_r2_service`; break;
                    case `cash`: boardDelta += 4; exposureDelta += 2; break;
                    case `cost`: boardDelta -= 4; exposureDelta += 8; ds.costMisaligned = true; coachKey = `coach_r2_cost`; break;
                    case `erp`: boardDelta -= 4; exposureDelta += 8; coachKey = `coach_r2_erp`; break;
                    case `everything`: boardDelta -= 6; exposureDelta += 6; coachKey = `coach_r2_everything`; break;
                }

                switch (d.count) {
                    case `few`: boardDelta += 8; exposureDelta -= 3; break;
                    case `some`: boardDelta += 2; break;
                    case `all`: boardDelta -= 6; exposureDelta += 5; if (coachKey === `coach_default`) coachKey = `coach_r2_allcount`; break;
                }

                switch (d.align) {
                    case `yes`: boardDelta += 8; exposureDelta -= 4; break;
                    case `partial`: boardDelta += 2; break;
                    case `no`: boardDelta -= 5; exposureDelta += 4; if (coachKey === `coach_default`) coachKey = `coach_r2_noalign`; break;
                }

                if (d.focus >= 60) { boardDelta += 5; exposureDelta -= 2; }
                else if (d.focus <= 25) { boardDelta -= 5; exposureDelta += 4; }

                summaryKey = (d.priority === `service` && d.count === `few` && d.align === `yes`) ? `sum_r2_good` :
                             ((d.priority === `cost` || d.priority === `erp` || d.priority === `everything`) ? `sum_r2_misaligned` : `sum_r2_weak`);
            } else if (round === 3) {
                // Decide: allocate the US$40M and sequence for early value (Pedagogy 3).
                const sop = d.sop, net = d.network, wc = d.wc, tal = d.talent, erp = d.erp, auto = d.auto;
                spend = sop + net + wc + tal + erp + auto;

                // S&OP is the highest-leverage, fastest-payback move — it lifts OTIF and releases cash.
                otifDelta += Math.min(4, sop * 0.55);
                cashDelta += Math.min(14, sop * 1.4);
                boardDelta += Math.min(8, sop * 1.0);

                // Network / DC redesign serves the customer and frees some cash.
                otifDelta += Math.min(3, net * 0.30);
                cashDelta += Math.min(8, net * 0.6);

                // Working-capital release is the self-funding lever off the 94-day cash-to-cash cycle.
                cashDelta += Math.min(this.EXCESS_INV, wc * 4.5);
                boardDelta += Math.min(6, wc * 1.0);

                // Talent & S&OP cadence — the enablers that make the assets work (Pedagogy 4).
                boardDelta += Math.min(7, tal * 1.2);
                otifDelta += Math.min(1.5, tal * 0.25);

                // ERP unification — heavy, slow, zero service before the customer's review.
                if (erp >= this.ERP_COST * 0.75) {
                    ds.erpFirst = true;
                    boardDelta -= 8; exposureDelta += 10; otifDelta -= 1;
                    coachKey = `coach_r3_erpfirst`;
                } else if (erp > 0) {
                    boardDelta += 1;
                }

                // Plant automation — capital-heavy, slow to land; modest cash, little near-term OTIF.
                cashDelta += Math.min(4, auto * 0.3);

                // Asset-buying without enablers (Common Error 4).
                if ((erp + auto) >= 20 && tal <= 2) {
                    ds.assetHeavy = true;
                    boardDelta -= 6; exposureDelta += 5;
                    if (coachKey === `coach_default`) coachKey = `coach_r3_noenablers`;
                }

                // Deliberate Phase-1 first move (sequencing for provable value).
                switch (d.phase) {
                    case `sop`: otifDelta += 2; cashDelta += 4; boardDelta += 8; exposureDelta -= 8; if (coachKey === `coach_default`) coachKey = `coach_r3_sopfirst`; break;
                    case `erp`: ds.erpFirst = true; boardDelta -= 6; exposureDelta += 8; otifDelta -= 1; if (coachKey === `coach_default`) coachKey = `coach_r3_erpfirst`; break;
                    case `auto`: boardDelta -= 3; exposureDelta += 4; if (coachKey === `coach_default`) coachKey = `coach_r3_autofirst`; break;
                }

                if (coachKey === `coach_default`) coachKey = `coach_r3_balanced`;

                summaryKey = (sop >= 5 && wc >= 3 && tal >= 3 && d.phase === `sop` && !ds.erpFirst) ? `sum_r3_good` :
                             (ds.erpFirst ? `sum_r3_erp` : `sum_r3_weak`);
            } else if (round === 4) {
                // Defend: the board brief & Phase-1 gate (Pedagogy 5).
                switch (d.test) {
                    case `quantified`: boardDelta += 14; exposureDelta -= 8; coachKey = `coach_r4_quantified`; break;
                    case `directional`: boardDelta += 2; exposureDelta += 2; coachKey = `coach_r4_directional`; break;
                    case `none`: boardDelta -= 10; exposureDelta += 10; ds.noGateTest = true; coachKey = `coach_r4_notest`; break;
                }

                switch (d.fund) {
                    case `self`: boardDelta += 10; exposureDelta -= 4; if (d.test === `quantified`) coachKey = `coach_r4_selffund`; break;
                    case `mixed`: boardDelta += 2; break;
                    case `ask`: boardDelta -= 6; exposureDelta += 4; if (coachKey === `coach_r4_quantified`) coachKey = `coach_r4_askfund`; break;
                }

                switch (d.risk) {
                    case `contingency`: boardDelta += 8; exposureDelta -= 6; break;
                    case `escalate`: boardDelta -= 2; exposureDelta += 3; break;
                    case `confident`: boardDelta -= 6; exposureDelta += 6; coachKey = `coach_r4_overconfident`; break;
                }

                if (d.conviction >= 60) { boardDelta += 5; exposureDelta -= 3; }
                else if (d.conviction <= 25) { boardDelta -= 5; exposureDelta += 4; }

                summaryKey = (d.test === `quantified` && d.fund === `self` && d.risk === `contingency`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: the US$40M budget is metered by the R3 allocation.
            ds.budgetUsed = Math.min(this.BUDGET, Math.round(ds.budgetUsed + spend));

            // Apply deltas, clamped. OTIF 0–100 (target 96); board/exposure 0–100; cash accrues.
            ds.otif = Math.max(80, Math.min(100, Math.round((ds.otif + otifDelta) * 10) / 10));
            ds.cashReleased = Math.max(0, Math.min(this.EXCESS_INV, Math.round(ds.cashReleased + cashDelta)));
            ds.board = Math.max(0, Math.min(100, Math.round(ds.board + boardDelta)));
            ds.exposure = Math.max(0, Math.min(100, Math.round(ds.exposure + exposureDelta)));

            ds.otifHistory.push(ds.otif);
            ds.cashHistory.push(ds.cashReleased);
            ds.boardHistory.push(ds.board);
            ds.exposureHistory.push(ds.exposure);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            return {
                period: state.currentPeriod,
                otif: ds.otif,
                otifDelta: Math.round(otifDelta * 10) / 10,
                cashReleased: ds.cashReleased,
                cashDelta: Math.round(cashDelta),
                board: ds.board,
                boardDelta: Math.round(boardDelta),
                exposure: ds.exposure,
                exposureDelta: Math.round(exposureDelta),
                budgetUsed: ds.budgetUsed,
                erpFirst: ds.erpFirst,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // USD only: "$40M", negatives "-$5M". Whole millions read cleanly at VP/board level.
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(Math.round(v));
            return `${sign}$${abs}M`;
        }

