            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`otifDisplay`, `domainState.otif`, (v) => {
                const card = document.querySelector(`.smfsim-card-otif`);
                if (card) {
                    card.classList.toggle(`smfsim-otif-good`, Number(v) >= self.OTIF_TARGET);
                    card.classList.toggle(`smfsim-otif-bad`, Number(v) < 90);
                }
                const n = Number(v);
                return (Math.round(n) === n ? n.toFixed(0) : n.toFixed(1)) + `%`;
            });
            uiManager.bind(`cashDisplay`, `domainState.cashReleased`, (v) => self._fmtMoney(Number(v)));
            uiManager.bind(`boardDisplay`, `domainState.board`, (v) => Math.round(Number(v)));
            uiManager.bind(`exposureDisplay`, `domainState.exposure`, (v) => {
                const card = document.querySelector(`.smfsim-card-exposure`);
                if (card) {
                    card.classList.toggle(`smfsim-exposure-high`, Number(v) >= 60);
                    card.classList.toggle(`smfsim-exposure-low`, Number(v) <= 25);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.BUDGET);
