            // Position slider readout.
            const po = document.getElementById(`positionInput`);
            const poReadout = document.getElementById(`positionReadout`);
            if (po && poReadout) {
                poReadout.textContent = po.value;
                po.addEventListener(`input`, function() { poReadout.textContent = po.value; });
            }

            // Focus slider readout.
            const fo = document.getElementById(`focusInput`);
            const foReadout = document.getElementById(`focusReadout`);
            if (fo && foReadout) {
                foReadout.textContent = fo.value;
                fo.addEventListener(`input`, function() { foReadout.textContent = fo.value; });
            }

            // Live budget total — must hit exactly $40M.
            const allocIds = [`sopInput`, `networkInput`, `wcInput`, `talentInput`, `erpInput`, `autoInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (allocReadout) allocReadout.textContent = total.toFixed(0);
                const bar = document.querySelector(`.smfsim-alloc-readout`);
                if (bar) bar.style.color = (total !== self.BUDGET) ? `#c4391a` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

