        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.otifHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                smfChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.otifHistory },
                        { data: ds.boardHistory },
                        { data: ds.exposureHistory }
                    ]
                }
            };
        }

        // _composite(ds): single source of truth for the 0-100 score (v1.0.0 formula, verbatim).
        _composite(ds) {
            const otif = ds.otif;
            const cash = Math.round(ds.cashReleased);
            const board = Math.round(ds.board);
            const exposure = Math.round(ds.exposure);
            const otifScore = Math.max(0, Math.min(100, (otif - 80) * 5));
            const cashScore = Math.min(25, cash * 0.7);
            return Math.round(otifScore * 0.30 + board * 0.30 + (100 - exposure) * 0.24 + cashScore * 0.64);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const otif = ds.otif;
            const cash = Math.round(ds.cashReleased);
            const board = Math.round(ds.board);
            const exposure = Math.round(ds.exposure);

            // Composite via _composite(ds) — single source of truth (v1.0.0 formula).
            const composite = this._composite(ds);

            const serviceRestored = otif >= 94;
            const selfFunding = cash >= 25;
            const boardBought = board >= 60 && exposure <= 35;
            const erpTrap = ds.erpFirst && otif < 94;

            let performanceKey = `grade_stalled`;
            if (serviceRestored && selfFunding && boardBought && composite >= 75) performanceKey = `grade_integrated`;
            else if (serviceRestored && boardBought) performanceKey = `grade_gate`;
            else if (erpTrap) performanceKey = `grade_erp`;
            else if (ds.costMisaligned && otif < 92) performanceKey = `grade_misaligned`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (serviceRestored && selfFunding && boardBought) insights.push(window.mySimulation.t(`insight_integrated`));
            else if (erpTrap) insights.push(window.mySimulation.t(`insight_erp`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (otif < 94) insights.push(window.mySimulation.t(`insight_otif_low`));
            else insights.push(window.mySimulation.t(`insight_otif_recovered`));
            if (cash < 25) insights.push(window.mySimulation.t(`insight_cash_trapped`));
            else insights.push(window.mySimulation.t(`insight_cash_freed`));
            if (ds.noGateTest) insights.push(window.mySimulation.t(`insight_nogate`));
            if (ds.costMisaligned) insights.push(window.mySimulation.t(`insight_misaligned`));

            return {
                otif: otif,
                cash: cash,
                board: board,
                exposure: exposure,
                serviceRestored: serviceRestored,
                selfFunding: selfFunding,
                boardBought: boardBought,
                erpTrap: erpTrap,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: (serviceRestored && selfFunding && boardBought),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const s = summary || {};
            const t = (k) => window.mySimulation.t(k);
            const esc = (x) => String(x == null ? `` : x).replace(/[&<>]/g, (c) => ({ '&': `&amp;`, '<': `&lt;`, '>': `&gt;` }[c]));
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || t(s.performanceKey || `grade_stalled`);
            const badge = (ok, okKey, noKey) => `<span class="smfsim-cm-badge ${ok ? `smfsim-cm-ok` : `smfsim-cm-no`}">${esc(t(ok ? okKey : noKey))}</span>`;
            const kpi = (label, val) => `<div class="smfsim-cm-kpi"><div class="smfsim-cm-kpi-v">${esc(val)}</div><div class="smfsim-cm-kpi-l">${esc(label)}</div></div>`;
            const insights = (s.insights || []).map((i) => `<li>${esc(i)}</li>`).join(``);
            let badges = badge(s.serviceRestored === true, `cm_badge_service`, `cm_badge_stalledsvc`)
                       + badge(s.selfFunding === true, `cm_badge_selffund`, `cm_badge_cashtrapped`)
                       + badge(s.boardBought === true, `cm_badge_board`, `cm_badge_noboard`);
            if (s.erpTrap) badges += `<span class="smfsim-cm-badge smfsim-cm-no">${esc(t(`cm_badge_erptrap`))}</span>`;
            const cash = (s.cash != null) ? this._fmtMoney(Number(s.cash)) : `\u2014`;
            return `<div class="smfsim-cm">`
                + `<div class="smfsim-cm-head"><div class="smfsim-cm-score">${score}<span class="smfsim-cm-max">/100</span></div>`
                + `<div class="smfsim-cm-grade">${esc(grade)}</div></div>`
                + `<div class="smfsim-cm-badges">${badges}</div>`
                + `<div class="smfsim-cm-kpis">`
                + kpi(t(`cm_kpi_otif`), (s.otif != null ? s.otif + `%` : `\u2014`))
                + kpi(t(`cm_kpi_cash`), cash)
                + kpi(t(`cm_kpi_board`), (s.board != null ? s.board : `\u2014`))
                + kpi(t(`cm_kpi_exposure`), (s.exposure != null ? s.exposure : `\u2014`))
                + kpi(t(`cm_kpi_index`), score)
                + `</div>`
                + (insights ? `<ul class="smfsim-cm-insights">${insights}</ul>` : ``)
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.erpFirst) return window.mySimulation.t(`hint_erp`);
            if (ds.costMisaligned && ds.otif < 92) return window.mySimulation.t(`hint_misaligned`);
            if (state.currentPeriod >= 3 && ds.cashReleased < 15) return window.mySimulation.t(`hint_cash`);
            if (ds.exposure >= 65) return window.mySimulation.t(`hint_exposure`);
            if (state.currentPeriod >= 3 && ds.otif < 92) return window.mySimulation.t(`hint_otif`);
            if (ds.otif >= 94 && ds.board >= 60 && ds.exposure <= 30) return window.mySimulation.t(`hint_strong`);
            return null;
        }

